// pathfinding.js
// ============================================================================
// TOPOGRAPHIC A* (A-STAR) PATHFINDING & TRAJECTORY SMOOTHING ENGINE
// ============================================================================

import { WMS_BASE_URL } from './constants.js';

/**
 * Line-of-sight string-pulling algorithm that removes unnecessary staircase zig-zags
 * generated by discrete 8-way grid movement.
 * @param {Array<{x: number, y: number}>} path - Raw array of grid coordinates from A*.
 * @param {Array<Array<number>>} grid - 2D elevation matrix.
 * @param {number} maxLookAhead - Maximum number of nodes ahead to check for a direct shortcut.
 * @param {number} elevTolerance - Maximum allowed elevation change along a shortcut segment.
 * @returns {Array<{x: number, y: number}>} Pruned path array.
 */
export function pruneMicroZigZags(path, grid, maxLookAhead, elevTolerance) {
    if (path.length <= 2) return path;
    const pruned = [path[0]];
    let currentIdx = 0;

    while (currentIdx < path.length - 1) {
        let furthestVisible = currentIdx + 1;
        const limit = Math.min(path.length - 1, currentIdx + maxLookAhead);

        // Scan backwards from the furthest look-ahead point to find the longest safe straight line
        for (let checkIdx = limit; checkIdx > currentIdx + 1; checkIdx--) {
            if (isSegmentFlat(path[currentIdx], path[checkIdx], grid, elevTolerance)) {
                furthestVisible = checkIdx;
                break;
            }
        }
        pruned.push(path[furthestVisible]);
        currentIdx = furthestVisible;
    }
    return pruned;
}

/**
 * Helper function that samples points along a straight line between p1 and p2
 * to verify that it does not cross impassable voids (-1) or steep cliffs.
 */
function isSegmentFlat(p1, p2, grid, tolerance) {
    const steps = Math.max(Math.abs(p2.x - p1.x), Math.abs(p2.y - p1.y)) * 2;
    const startElev = grid[Math.round(p1.y)][Math.round(p1.x)];
    let prevElev = startElev;

    for (let i = 1; i <= steps; i++) {
        const t = i / steps;
        const x = Math.round(p1.x + (p2.x - p1.x) * t);
        const y = Math.round(p1.y + (p2.y - p1.y) * t);
        const currElev = grid[y][x];

        // Reject shortcut if it crosses a NoData void (-1)
        if (currElev === -1) return false;

        // Reject shortcut if step-to-step slope or cumulative elevation change exceeds tolerance
        if (Math.abs(currElev - prevElev) > tolerance || Math.abs(currElev - startElev) > tolerance * 1.4) {
            return false;
        }
        prevElev = currElev;
    }
    return true;
}

/**
 * Chaikin's corner-cutting algorithm to convert sharp polygon vertices into smooth curves.
 * @param {Array<{x: number, y: number}>} pts - Input array of 2D points.
 * @param {number} iterations - Number of smoothing passes.
 * @returns {Array<{x: number, y: number}>} Smoothed path array.
 */
export function chaikinSmooth(pts, iterations) {
    let current = pts;
    for (let iter = 0; iter < iterations; iter++) {
        if (current.length <= 2) break;
        const next = [current[0]]; // Preserve start point

        for (let i = 0; i < current.length - 1; i++) {
            const p0 = current[i];
            const p1 = current[i + 1];
            // Generate two new points at 25% and 75% along each segment
            next.push({ x: 0.75 * p0.x + 0.25 * p1.x, y: 0.75 * p0.y + 0.25 * p1.y });
            next.push({ x: 0.25 * p0.x + 0.75 * p1.x, y: 0.25 * p0.y + 0.75 * p1.y });
        }
        next.push(current[current.length - 1]); // Preserve end point
        current = next;
    }
    return current;
}

/**
 * Core A* (A-Star) Pathfinding algorithm that evaluates both Euclidean distance
 * and non-linear topographic slope penalties over a 2D elevation grid.
 * @param {Array<Array<number>>} grid - 2D array of elevation values (0-255, or -1 for obstacles).
 * @param {number} size - Dimension of the square grid.
 * @param {{x: number, y: number}} start - Starting grid node.
 * @param {{x: number, y: number}} end - Target grid node.
 * @param {number} slopeWeight - Multiplier for penalizing elevation changes.
 * @returns {Array<{x: number, y: number}>} Optimal sequence of grid nodes from start to end.
 */
export function findOptimalRouteOnGrid(grid, size, start, end, slopeWeight) {
    const openSet = [start];
    const cameFrom = new Map();
    const gScore = Array.from({ length: size }, () => Array(size).fill(Infinity));
    const fScore = Array.from({ length: size }, () => Array(size).fill(Infinity));

    const key = (p) => `${p.x},${p.y}`;
    gScore[start.y][start.x] = 0;
    fScore[start.y][start.x] = Math.hypot(end.x - start.x, end.y - start.y);

    // 8-way connectivity movement vectors (Orthogonal cost = 1, Diagonal cost = sqrt(2))
    const dirs = [
        {x:1, y:0, d:1}, {x:-1, y:0, d:1}, {x:0, y:1, d:1}, {x:0, y:-1, d:1},
        {x:1, y:1, d:1.414}, {x:-1, y:1, d:1.414}, {x:1, y:-1, d:1.414}, {x:-1, y:-1, d:1.414}
    ];

    while (openSet.length > 0) {
        // Sort openSet queue to process the node with the lowest F-score first
        openSet.sort((a, b) => fScore[a.y][a.x] - fScore[b.y][b.x]);
        const current = openSet.shift();

        // Goal reached: reconstruct and return the optimal path
        if (current.x === end.x && current.y === end.y) {
            const totalPath = [current];
            let currKey = key(current);
            while (cameFrom.has(currKey)) {
                const prev = cameFrom.get(currKey);
                totalPath.unshift(prev);
                currKey = key(prev);
            }
            return totalPath;
        }

        const parent = cameFrom.get(key(current));

        // Evaluate all 8 neighboring grid cells
        for (const dir of dirs) {
            const nx = current.x + dir.x;
            const ny = current.y + dir.y;

            // Skip out-of-bounds cells or impassable NoData voids (-1)
            if (nx < 0 || nx >= size || ny < 0 || ny >= size) continue;
            if (grid[ny][nx] === -1) continue;

            // Compute exponential slope penalty so the rover strongly prefers flat valleys
            const elevDiff = Math.abs(grid[ny][nx] - grid[current.y][current.x]);
            const slopePenalty = Math.pow(elevDiff, 2.35) * slopeWeight;

            // Apply a minor turn penalty to discourage unnecessary zig-zagging on flat plains
            let turnPenalty = 0;
            if (parent) {
                if (current.x - parent.x !== dir.x || current.y - parent.y !== dir.y) {
                    turnPenalty = 0.12;
                }
            }

            const tentativeG = gScore[current.y][current.x] + dir.d + slopePenalty + turnPenalty;

            // If a cheaper path to the neighbor is found, record it
            if (tentativeG < gScore[ny][nx]) {
                cameFrom.set(key({x: nx, y: ny}), current);
                gScore[ny][nx] = tentativeG;
                fScore[ny][nx] = tentativeG + Math.hypot(end.x - nx, end.y - ny);
                if (!openSet.some(p => p.x === nx && p.y === ny)) {
                    openSet.push({x: nx, y: ny});
                }
            }
        }
    }
    return []; // Return empty array if no valid path exists
}

/**
 * Fallback global pathfinder when either Point A or Point B lies outside the local HiRISE bounds.
 * Dynamically requests a WMS map tile from USGS MOLA, converts pixel colors to elevation, and runs A*.
 * @param {{lon: number, lat: number}} pA - Starting geographic coordinate.
 * @param {{lon: number, lat: number}} pB - Target geographic coordinate.
 * @returns {Promise<Array<Cesium.Cartesian3>>} Array of 3D Cesium world positions forming the route.
 */
export async function computeGlobalMolaAStarRoute(pA, pB) {
    const lonSpan = Math.abs(pB.lon - pA.lon);
    const latSpan = Math.abs(pB.lat - pA.lat);
    const pad = Math.max(lonSpan, latSpan, 0.4) * 0.35; // Add 35% bounding box padding

    const minLon = Math.min(pA.lon, pB.lon) - pad;
    const maxLon = Math.max(pA.lon, pB.lon) + pad;
    const minLat = Math.min(pA.lat, pB.lat) - pad;
    const maxLat = Math.max(pA.lat, pB.lat) + pad;

    const MOLA_GRID = 150;
    const wmsUrl = `${WMS_BASE_URL}&SERVICE=WMS&VERSION=1.1.1&REQUEST=GetMap&LAYERS=MOLA_color&STYLES=&SRS=EPSG:4326&BBOX=${minLon},${minLat},${maxLon},${maxLat}&WIDTH=${MOLA_GRID}&HEIGHT=${MOLA_GRID}&FORMAT=image/png`;

    return new Promise((resolve) => {
        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.src = wmsUrl;

        img.onload = function() {
            const canvas = document.createElement('canvas');
            canvas.width = MOLA_GRID;
            canvas.height = MOLA_GRID;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(img, 0, 0, MOLA_GRID, MOLA_GRID);
            const data = ctx.getImageData(0, 0, MOLA_GRID, MOLA_GRID).data;

            // Build 2D elevation matrix from MOLA hypsometric tint RGB values
            const molaGrid = Array.from({ length: MOLA_GRID }, () => new Array(MOLA_GRID));
            for (let y = 0; y < MOLA_GRID; y++) {
                for (let x = 0; x < MOLA_GRID; x++) {
                    const idx = (y * MOLA_GRID + x) * 4;
                    molaGrid[y][x] = rgbToMolaElevation(data[idx], data[idx + 1], data[idx + 2]);
                }
            }

            // Map geographic coordinates to discrete grid indices
            const startNode = {
                x: Math.min(MOLA_GRID - 1, Math.max(0, Math.floor(((pA.lon - minLon) / (maxLon - minLon)) * (MOLA_GRID - 1)))),
                y: Math.min(MOLA_GRID - 1, Math.max(0, Math.floor(((maxLat - pA.lat) / (maxLat - minLat)) * (MOLA_GRID - 1))))
            };
            const endNode = {
                x: Math.min(MOLA_GRID - 1, Math.max(0, Math.floor(((pB.lon - minLon) / (maxLon - minLon)) * (MOLA_GRID - 1)))),
                y: Math.min(MOLA_GRID - 1, Math.max(0, Math.floor(((maxLat - pB.lat) / (maxLat - minLat)) * (MOLA_GRID - 1))))
            };

            const rawPath = findOptimalRouteOnGrid(molaGrid, MOLA_GRID, startNode, endNode, 3.2);
            if (rawPath.length > 0) {
                const pruned = pruneMicroZigZags(rawPath, molaGrid, 3, 2.0);
                const smoothed = chaikinSmooth(pruned, 1);

                // Convert smoothed grid nodes back into 3D Cesium Cartesian coordinates
                const positions = smoothed.map(p => {
                    const lon = minLon + (p.x / (MOLA_GRID - 1)) * (maxLon - minLon);
                    const lat = maxLat - (p.y / (MOLA_GRID - 1)) * (maxLat - minLat);
                    return Cesium.Cartesian3.fromDegrees(lon, lat, 80);
                });
                resolve(positions);
            } else {
                // Fallback to direct straight line if pathfinding fails
                resolve([Cesium.Cartesian3.fromDegrees(pA.lon, pA.lat, 80), Cesium.Cartesian3.fromDegrees(pB.lon, pB.lat, 80)]);
            }
        };

        // Fallback to direct straight line if WMS image fails to load
        img.onerror = () => resolve([Cesium.Cartesian3.fromDegrees(pA.lon, pA.lat, 80), Cesium.Cartesian3.fromDegrees(pB.lon, pB.lat, 80)]);
    });
}

/**
 * Approximates relative elevation (0-255) from USGS MOLA color-coded hypsometric tint RGB pixels.
 */
function rgbToMolaElevation(r, g, b) {
    const brightness = (r + g + b) / 3.0;
    if (brightness < 42) return 240; // Treat deep black shadows/crater walls as high-cost obstacles
    let elev = (r * 0.65) + (g * 0.25) - (b * 0.45) + 60;
    return Math.max(0, Math.min(255, elev));
}